        $null -eq [Environment]::GetEnvironmentVariable('NO_COLOR')) {
        switch ($level) {
            'ERROR' { $colour = '1;31' }
            'FAIL' { $colour = '1;31' }
            'WARN' { $colour = '1;33' }
            'NEXT' { $colour = '1;36' }
            'OK' { $colour = '1;32' }
        }
    }
